def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    last_me, last_op = history[-1]

    opp_d = 0
    my_d = 0
    for m, o in history:
        if o == 'D':
            opp_d += 1
        if m == 'D':
            my_d += 1

    start = n - 10
    if start < 0:
        start = 0
    recent_c = 0
    for i in range(start, n):
        if history[i][1] == 'C':
            recent_c += 1

    high = recent_c >= 6

    if last_op == 'C':
        # If the opponent has never defected, a delayed confirmation pattern
        # lets us exploit pure cooperators while keeping a single test cheap
        # against tit-for-tat-like players.
        if opp_d == 0:
            if my_d >= 2:
                return 'D'
            if my_d == 1 and last_me == 'C' and n >= 3:
                if history[-2][0] == 'D' and history[-2][1] == 'C':
                    return 'D'
            if my_d == 0 and n == 60 and recent_c == 10:
                return 'D'
        return 'C'

    s = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'D':
            s += 1
        else:
            break

    # After a short punishment, a failed cooperation attempt gets one extra
    # chance before returning to defection.
    if n >= 2 and last_me == 'C' and history[-2][0] == 'D' and history[-2][1] == 'D':
        return 'C'

    if s == 1:
        # First observed defection after an opponent cooperation: usually
        # try to restore cooperation immediately.
        if n >= 2 and history[-2][1] == 'C':
            return 'C'
        return 'D'

    if high:
        if s == 2:
            return 'D'
        if s == 3:
            return 'C'
        if s == 4:
            return 'D'
        if s >= 5 and last_me == 'D' and rng.random() < 0.05:
            return 'C'
        return 'D'

    if s >= 5 and last_me == 'D' and rng.random() < 0.04:
        return 'C'

    return 'D'
